#include <stdint.h>

const uint8_t mask = 0x01;

void setup() {
  uint8_t cppValue = 0x0F;
  cppValue ^= mask;  // daşına bilən C++ nəticəsi: 0x0E

  uint8_t asmValue = 0x0F;
  // AVR-GCC üçün inline assembly; bütün Arduino lövhələrinə uyğun deyil.
  asm volatile (
    "eor %0, %1"
    : "+r" (asmValue)  // çıxış: registrdə oxunur və yazılır
    : "r" (mask)       // giriş: mask registrdədir
    : "cc"              // EOR şərt bayraqlarını dəyişir
  );                  // asmValue də 0x0E olur
  Serial.begin(9600);
  Serial.print(cppValue);
  Serial.print(' ');
  Serial.println(asmValue);  // yalnız nümunə nəticəsi; Serial vaxtını ölçməyin
}

void loop() {}
